#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/control/shared_capabilities/shared_capabilities.hpp"
#include "gui_forms/controls/breadcrumb_trail_values.hpp"
#include "gui_forms/types.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// BreadcrumbTrail's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/breadcrumb_trail.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// Whether the segments are drawn plain or as raised arrows. An undeclared value throws std::invalid_argument; a change re-lays out the segments.
template <typename Declaring>
struct BreadcrumbTrailAppearanceCapability {
    PropertyCell<BreadcrumbAppearance, BreadcrumbTrailAppearanceCapability<Declaring>> appearance{BreadcrumbAppearance::plain};

    static void assign(BreadcrumbTrailAppearanceCapability& capability, BreadcrumbAppearance incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.appearance), incoming);
        if (!capability.appearance.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.appearance));
    }
};

// The stable ID of the keyboard-active segment, the overflow or the edit button, or empty; a view, since keyboard, pointer and semantic actions move it. An ID not in the model throws std::out_of_range.
template <typename Declaring>
struct BreadcrumbTrailActiveIdCapability {
    PropertyView<std::string, BreadcrumbTrailActiveIdCapability<Declaring>> active_id;

    static void assign(BreadcrumbTrailActiveIdCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.active_id), std::move(incoming));
    }

    static std::string read(const BreadcrumbTrailActiveIdCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::string current = control.read_view(capability.active_id);
        return current;
    }
};

// Whether the exact-path editor replaces the segments. Ending an edit withdraws tab completion. begin_edit fills the editor and turns it on.
template <typename Declaring>
struct BreadcrumbTrailEditingCapability {
    PropertyCell<bool, BreadcrumbTrailEditingCapability<Declaring>> editing{};

    static void assign(BreadcrumbTrailEditingCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.editing), incoming);
        if (!capability.editing.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.editing));
    }
};

// Whether Tab in the path editor requests completion (edit_completion_requested). It holds only while editing; a write outside an edit stores false.
template <typename Declaring>
struct BreadcrumbTrailTabCompletionAvailableCapability {
    PropertyCell<bool, BreadcrumbTrailTabCompletionAvailableCapability<Declaring>> tab_completion_available{};

    static void assign(BreadcrumbTrailTabCompletionAvailableCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.tab_completion_available), incoming);
        if (!capability.tab_completion_available.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.tab_completion_available));
    }
};

// Every BreadcrumbTrail capability, in the order the declaring class takes them.
template <typename Declaring>
struct BreadcrumbTrailCapabilities : public FontCapability<Declaring>,
                                     public BreadcrumbTrailAppearanceCapability<Declaring>,
                                     public BreadcrumbTrailActiveIdCapability<Declaring>,
                                     public BreadcrumbTrailEditingCapability<Declaring>,
                                     public BreadcrumbTrailTabCompletionAvailableCapability<Declaring> {
    BreadcrumbTrailCapabilities() : FontCapability<Declaring>(FontSpec{FontRole::control, 10.5, 400, false}) {}
};

} // namespace gui_forms
